import React, { useState } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { motion } from 'framer-motion';

const Sidebar: React.FC = () => {
  const [isCollapsed, setIsCollapsed] = useState(false);
  const location = useLocation();

  const navigation = [
    { name: 'Home', href: '/', icon: '🏠' },
    { name: 'Matches', href: '/matches', icon: '⚽' },
    { name: 'My Teams', href: '/profile', icon: '👥' },
    { name: 'Leaderboard', href: '/leaderboard', icon: '🏆' },
    { name: 'History', href: '/history', icon: '📊' },
    { name: 'Notifications', href: '/notifications', icon: '🔔' },
  ];

  return (
    <motion.div
      initial={{ x: -250 }}
      animate={{ x: 0 }}
      className={`fixed left-0 top-16 h-full bg-white border-r border-gray-200 z-40 transition-all duration-300 ${
        isCollapsed ? 'w-16' : 'w-64'
      } lg:block hidden`}
    >
      {/* Toggle Button */}
      <button
        onClick={() => setIsCollapsed(!isCollapsed)}
        className="absolute -right-3 top-6 bg-white border border-gray-200 rounded-full w-6 h-6 flex items-center justify-center hover:bg-gray-50"
      >
        <span className={`text-xs transition-transform ${isCollapsed ? 'rotate-180' : ''}`}>
          ◀
        </span>
      </button>

      {/* Navigation */}
      <nav className="mt-8 px-4">
        <ul className="space-y-2">
          {navigation.map((item) => {
            const isActive = location.pathname === item.href || 
              (item.href !== '/' && location.pathname.startsWith(item.href));
            
            return (
              <li key={item.name}>
                <Link
                  to={item.href}
                  className={`group flex items-center px-3 py-2 text-sm font-medium rounded-lg transition-colors duration-200 ${
                    isActive
                      ? 'bg-primary-50 text-primary-700 border-r-2 border-primary-500'
                      : 'text-gray-600 hover:bg-gray-50 hover:text-gray-900'
                  }`}
                >
                  <span className="text-xl mr-3">{item.icon}</span>
                  {!isCollapsed && (
                    <motion.span
                      initial={{ opacity: 0 }}
                      animate={{ opacity: 1 }}
                      exit={{ opacity: 0 }}
                    >
                      {item.name}
                    </motion.span>
                  )}
                </Link>
              </li>
            );
          })}
        </ul>
      </nav>

      {/* Quick Stats */}
      {!isCollapsed && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          className="mt-8 px-4"
        >
          <div className="bg-gradient-to-br from-primary-50 to-primary-100 rounded-lg p-4">
            <h3 className="text-sm font-semibold text-primary-800 mb-2">
              Quick Stats
            </h3>
            <div className="space-y-2">
              <div className="flex justify-between text-xs">
                <span className="text-primary-600">Contests Won</span>
                <span className="font-semibold text-primary-800">12</span>
              </div>
              <div className="flex justify-between text-xs">
                <span className="text-primary-600">Win Rate</span>
                <span className="font-semibold text-primary-800">65.5%</span>
              </div>
              <div className="flex justify-between text-xs">
                <span className="text-primary-600">Total Winnings</span>
                <span className="font-semibold text-primary-800">₹15,000</span>
              </div>
            </div>
          </div>
        </motion.div>
      )}

      {/* Upcoming Matches */}
      {!isCollapsed && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          className="mt-6 px-4"
        >
          <h3 className="text-sm font-semibold text-gray-800 mb-3">
            Upcoming Matches
          </h3>
          <div className="space-y-3">
            <div className="bg-gray-50 rounded-lg p-3">
              <div className="flex items-center justify-between text-xs">
                <div>
                  <div className="font-medium text-gray-900">MAN vs LIV</div>
                  <div className="text-gray-500">2 hours left</div>
                </div>
                <div className="text-primary-600 font-semibold">24 contests</div>
              </div>
            </div>
            <div className="bg-gray-50 rounded-lg p-3">
              <div className="flex items-center justify-between text-xs">
                <div>
                  <div className="font-medium text-gray-900">CHE vs ARS</div>
                  <div className="text-gray-500">4 hours left</div>
                </div>
                <div className="text-primary-600 font-semibold">18 contests</div>
              </div>
            </div>
          </div>
        </motion.div>
      )}
    </motion.div>
  );
};

export default Sidebar;
